from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_form_then_file():
    # This is the case that is reported to fail
    response = client.post(
        "/test",
        data={"form_data": "hello"},
        files={"file": ("test.txt", b"content")}
    )
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

def test_file_then_form():
    # This is the case that is reported to work
    @app.post("/test-reversed")
    async def test_reversed_endpoint(file: UploadFile = File(...), form_data: str = Form(...)):
        return {"form_data": form_data, "file": file.filename}

    response = client.post(
        "/test-reversed",
        data={"form_data": "hello"},
        files={"file": ("test.txt", b"content")}
    )
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed")
    except Exception as e:
        print(f"test_form_then_file failed: {e}")

    try:
        test_file_then_form()
        print("test_file_then_form passed")
    except Exception as e:
        print(f"test_file_then_form failed: {e}")

